        <!-- ═══════════ DEPARTMENTAL BOARD ═══════════ -->
        <section data-aos="fade-up" id="departmental-board" style="margin-bottom: 4rem;">
            <div class="section-heading" style="display: flex; align-items: center; gap: 1rem; margin-bottom: 1.5rem;">
                <div class="section-heading-icon" style="width: 48px; height: 48px; background: linear-gradient(135deg, rgba(22, 163, 74, 0.15), rgba(16, 185, 129, 0.1)); color: var(--color-primary); border-radius: 14px; display: flex; align-items: center; justify-content: center; font-size: 1.3rem;">
                    <i class="fa-solid fa-sitemap"></i>
                </div>
                <h2 style="margin: 0; font-size: 2rem; color: #0f172a; font-family: var(--font-heading); font-weight: 700;">Departmental Board</h2>
            </div>
            <div style="width: 60px; height: 4px; background: linear-gradient(90deg, var(--color-primary), var(--color-accent)); margin-bottom: 2rem; border-radius: 2px;"></div>

            <p style="font-size: 1.02rem; color: #475569; line-height: 1.7; margin-bottom: 2rem;">The Departmental Board is made up of all lecturers in the Department except Graduate Assistants, with the Head of Department as the Chairman. The Board organizes and controls the teaching of all courses and the examinations held in those courses.</p>

            <div class="about-board-grid" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 1.2rem;">
                <!-- Chairman -->
                <div data-aos="fade-up" class="about-board-card hover-lift" style="background: linear-gradient(135deg, #064e3b 0%, #065f46 100%); border-radius: 14px; padding: 1.8rem; color: white; text-align: center; position: relative; overflow: hidden; transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1);" onmouseover="this.style.transform='translateY(-6px)'; this.style.boxShadow='0 20px 40px -12px rgba(6,78,59,0.3)'" onmouseout="this.style.transform='translateY(0)'; this.style.boxShadow='none'">
                    <div style="position: absolute; inset: 0; background: radial-gradient(circle at 50% 0%, rgba(16,185,129,0.2), transparent 70%); pointer-events: none;"></div>
                    <div style="position: relative; z-index: 2; display: flex; flex-direction: column; align-items: center; justify-content: center; width: 100%; text-align: center;">
                        <div style="width: 56px; height: 56px; background: rgba(255,255,255,0.1); border: 2px solid rgba(255,255,255,0.2); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 1rem; font-size: 1.5rem; color: #a7f3d0; transition: transform 0.3s;" class="board-icon">
                            <i class="fa-solid fa-crown"></i>
                        </div>
                        <h4 style="margin: 0 0 0.3rem; font-size: 1.15rem; font-weight: 700; width: 100%; text-align: center;">Chairman</h4>
                        <p style="margin: 0; color: #6ee7b7; font-size: 0.9rem; width: 100%; text-align: center;">Head of Department (HOD)</p>
                    </div>
                </div>

                <!-- Members -->
                <div data-aos="fade-up" class="about-board-card hover-lift" style="background: linear-gradient(135deg, #f0fdf4, #ecfdf5); border-radius: 14px; padding: 1.8rem; text-align: center; border: 1px solid #bbf7d0; transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1); display: flex; flex-direction: column; align-items: center; justify-content: center;" onmouseover="this.style.transform='translateY(-6px)'; this.style.boxShadow='0 20px 40px -12px rgba(22,163,74,0.15)'" onmouseout="this.style.transform='translateY(0)'; this.style.boxShadow='none'">
                    <div style="width: 56px; height: 56px; background: rgba(22,163,74,0.1); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 1rem; font-size: 1.5rem; color: var(--color-primary); transition: transform 0.3s;" class="board-icon">
                        <i class="fa-solid fa-users"></i>
                    </div>
                    <h4 style="margin: 0 0 0.3rem; font-size: 1.15rem; color: #1e293b; font-weight: 700; width: 100%; text-align: center;">Members</h4>
                    <p style="margin: 0; color: #64748b; font-size: 0.9rem; width: 100%; text-align: center;">All Academic Staff<br><span style="font-size: 0.8rem; color: #94a3b8;">(Except Graduate Assistants)</span></p>
                </div>

                <!-- Mandate -->
                <div style="background: linear-gradient(135deg, #ecfdf5, #d1fae5); border-radius: 14px; padding: 2rem; text-align: center; border: 1px solid #a7f3d0; display: flex; flex-direction: column; align-items: center; justify-content: center;">
                    <div style="width: 64px; height: 64px; background: rgba(16,185,129,0.1); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 1.2rem; font-size: 1.8rem; color: #059669;">
                        <i class="fa-solid fa-clipboard-check"></i>
                    </div>
                    <h4 style="margin: 0 0 0.3rem; font-size: 1.15rem; color: #1e293b; font-weight: 700; width: 100%; text-align: center;">Mandate</h4>
                    <p style="margin: 0; color: #64748b; font-size: 0.9rem; width: 100%; text-align: center;">Course organisation, teaching oversight & examination control</p>
                </div>
            </div>
        </section>
